// Extract conversation data from webhook
// Access webhook data - it's nested under 'body' property
const inputData = $input.item.json;
const body = inputData.body || inputData;

// Extract fields with fallbacks
const sessionId = body.sessionId || `session-${Date.now()}`;
const userMessage = body.message;
const userId = body.userId || 'anonymous';
const channel = body.channel || 'web'; // web, whatsapp, sms, voice

// Validate required fields
if (!userMessage) {
  throw new Error('Message is required');
}

// Create structured output for next nodes
return {
  json: {
    sessionId: sessionId,
    userId: userId,
    userMessage: userMessage,
    channel: channel,
    timestamp: new Date().toISOString()
  }
};

// Build conversation history from memory
// Get original data from Extract Conversation Data node
const extractedData = $('Extract Conversation Data').first().json;
const currentMessage = extractedData.userMessage;
const sessionId = extractedData.sessionId;
const userId = extractedData.userId;
const channel = extractedData.channel;

// Get memory from Redis GET node (current input)
let conversationHistory = [];
try {
  const redisData = $input.first().json;

  // Redis GET operation returns the value directly or in various properties
  // Handle different possible response formats from Redis node
  let memoryData = null;

  // Check if we got a direct value (when key exists)
  if (typeof redisData === 'string') {
    memoryData = redisData;
  } 
  // Check common property names used by Redis node
  else if (redisData && typeof redisData === 'object') {
    // Try different property names that n8n Redis node might use
    memoryData = redisData.value || redisData.reply || redisData.data || redisData.result;

    // If propertyName is null or undefined, it means key doesn't exist
    if (redisData.propertyName === null || redisData.propertyName === undefined) {
      memoryData = null;
    }
  }

  // Parse the memory data if it exists and is not null
  if (memoryData && memoryData !== null && memoryData !== 'null') {
    conversationHistory = JSON.parse(memoryData);
  }
} catch (error) {
  // No previous memory or error parsing, start fresh
  console.log('Error parsing Redis memory, starting fresh:', error.message);
  conversationHistory = [];
}

// Ensure conversationHistory is an array
if (!Array.isArray(conversationHistory)) {
  conversationHistory = [];
}

// Add current message to history
conversationHistory.push({
  role: 'user',
  content: currentMessage,
  timestamp: new Date().toISOString()
});

// Keep only last 10 messages to manage token usage
if (conversationHistory.length > 10) {
  conversationHistory = conversationHistory.slice(-10);
}

return {
  json: {
    sessionId: sessionId,
    userId: userId,
    channel: channel,
    currentMessage: currentMessage,
    conversationHistory: conversationHistory
  }
};

// Check for emergency keywords
const message = $json.currentMessage.toLowerCase();
const emergencyKeywords = [
  'emergencia', 'urgente', 'no respira', 'convulsión', 'convulsion',
  'accidente', 'sangrado', 'inconsciente', 'desmayo', 'asfixia',
  'ahogo', 'muy grave', 'crisis', 'ataque'
];

const isEmergency = emergencyKeywords.some(keyword => message.includes(keyword));

return {
  json: {
    ...($json),
    isEmergency: isEmergency,
    requiresHumanEscalation: false // Will be determined by AI
  }
};

// Analyze AI response to determine if special actions needed
const aiResponse = $json.response?.content?.[0]?.text || $json.response?.text || '';
const conversationHistory = $input.first().json.conversationHistory;

// Check if response mentions appointments
const mentionsAppointment = /\b(cita|agendar|agenda|programar|reservar|appointment)\b/i.test(aiResponse);

// Check if response mentions pricing
const mentionsPricing = /\b(precio|costo|tarifa|cuanto cuesta|precio|pago|payment)\b/i.test(aiResponse);

// Check if collecting patient data
const collectingData = /\b(nombre|edad|teléfono|telefono|email|correo)\b/i.test(aiResponse);

// Add AI response to history
conversationHistory.push({
  role: 'assistant',
  content: aiResponse,
  timestamp: new Date().toISOString()
});

return {
  json: {
    sessionId: $input.first().json.sessionId,
    userId: $input.first().json.userId,
    channel: $input.first().json.channel,
    aiResponse: aiResponse,
    conversationHistory: conversationHistory,
    needsAppointmentCheck: mentionsAppointment,
    needsPricingCheck: mentionsPricing,
    collectingPatientData: collectingData,
    responseType: 'normal'
  }
};

